import java.util.*;

public class Hello {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine().trim();
        assert s.length() >= 1 && s.length() <= 8 : "Invalid input length";
        if (s.charAt(0) == '0') {
            System.out.println(s.length() > 1 ? "0" : "1");
            return;
        }
        int startRange = Integer.parseInt("1" + "0".repeat(s.length() - 1));
        if (startRange == 1) {
            startRange = 0;
        } else if (startRange == 10) {
            startRange = 25;
        }
        int endRange = Integer.parseInt("9".repeat(s.length()));
        int count = 0;
        for (int val = startRange; val <= endRange; val += 25) {
            if (matchesPattern(val, s)) {
                count++;
            }
        }
        System.out.println(count);
    }

    private static boolean matchesPattern(int num, String pattern) {
        String numStr = String.valueOf(num);
        char lastXChar = '*';
        for (int i = 0; i < pattern.length(); i++) {
            char pChar = pattern.charAt(i);
            if (pChar == '_') continue;
            if (pChar == 'X') {
                if (lastXChar != '*' && lastXChar != numStr.charAt(i)) return false;
                lastXChar = numStr.charAt(i);
            } else if (pChar != numStr.charAt(i)) {
                return false;
            }
        }
        return true;
    }
}
