using namespace std;

bool matchesPattern(int num, const string& pattern) {
    string numStr = to_string(num);
    char lastXChar = '*';
    for (size_t i = 0; i < pattern.size(); ++i) {
        char pChar = pattern[i];
        if (pChar == '_') continue;
        if (pChar == 'X') {
